def solve_grid(grid):
    """Fill interiors of hollow rectangular frames with 2"""
    rows = len(grid)
    cols = len(grid[0])

    result = [row[:] for row in grid]

    # For each potential top-left corner of a frame
    visited_cells = set()

    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]

            if color <= 4 or (r, c) in visited_cells:
                continue

            # Try to find a rectangular frame starting at (r, c)
            # First find right edge (how many consecutive 'color' pixels)
            c_right = c
            while c_right < cols and grid[r][c_right] == color:
                c_right += 1

            width = c_right - c
            if width < 3:
                continue  # Need at least 3-wide frame

            # Now find down edge (how many consecutive 'color' pixels at left)
            h_down = 1
            while r + h_down < rows and grid[r + h_down][c] == color:
                h_down += 1

            height = h_down - 1
            if height < 3:
                continue  # Need at least 3-tall frame

            # Verify complete rectangle exists
            # Check bottom edge
            bottom_ok = all(grid[r + height - 1][cc] == color 
                          for cc in range(c, c_right))
            # Check right edge
            right_ok = all(grid[rr][c_right - 1] == color 
                         for rr in range(r, r + height))

            if bottom_ok and right_ok:
                # Valid frame! Mark all cells
                for rr in range(r, r + height):
                    for cc in range(c, c_right):
                        visited_cells.add((rr, cc))

                # Fill interior with 2
                for rr in range(r + 1, r + height - 1):
                    for cc in range(c + 1, c_right - 1):
                        # Only fill if it's empty (background or different from color)
                        if grid[rr][cc] == 4 or grid[rr][cc] != color:
                            result[rr][cc] = 2

    return result

